{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Lambda invocation permission lacks source restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "HIGH",
      "explanation": "The API Gateway service principal can invoke this Lambda function without a SourceArn or SourceAccount restriction, allowing API Gateways from other AWS accounts to attempt invocation. Restricting the permission to the Lambda function's owning account reduces cross-account confused-deputy exposure."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_account = split(\":\", aws_lambda_function.log_processing_pipeline.arn)[4]\n}\n",
  "fix_summary": "Added a SourceAccount restriction derived from the Lambda function ARN, limiting API Gateway invocation permission to the function's owning AWS account."
}
